import fs from "node:fs/promises";
import crypto from "node:crypto";
import { buildArtifactLocation, getArtifactDir } from "../shared/artifact-paths.js";
import { formatApprovalSummaryList, formatWorkflowLabel, renderArtifactDocument } from "../shared/artifact-render.js";

export class ApprovalArtifactManager {
  constructor({ config, stateStore }) {
    this.config = config;
    this.stateStore = stateStore;
    this.artifactDir = getArtifactDir(config, "agent-approvals");
  }

  async exportApprovalArtifact({ approvalId = "", title = "" } = {}) {
    const approval = approvalId
      ? await this.stateStore.getApprovalRequest(approvalId)
      : (await this.stateStore.listApprovalRequests())[0] || null;

    if (!approval) {
      throw new Error("No approval record available to export.");
    }

    const workflowBundle = approval.workflowId ? await this.stateStore.getWorkflowBundle(approval.workflowId) : null;
    const traces = await this.stateStore.listTraces(300);
    const createdAt = new Date().toISOString();
    const safeTitle = slugify(title || approval.title || "approval").slice(0, 80) || "approval";
    const timestamp = createdAt.replace(/[:]/g, "-").replace(/\..+$/, "");
    const { absolutePath, storedPath } = buildArtifactLocation(this.config, "agent-approvals", `${timestamp}-${safeTitle}.md`);

    await fs.mkdir(this.artifactDir, { recursive: true });
    await fs.writeFile(
      absolutePath,
      renderApprovalDocument({ approval, workflowBundle, traces, title, createdAt }),
      "utf8"
    );

    const record = {
      id: `approvalartifact_${crypto.randomUUID()}`,
      createdAt,
      approvalId: approval.id,
      workflowId: approval.workflowId || null,
      title: title || approval.title || "approval",
      path: storedPath,
      approvalSummary: approval.summary
    };

    await this.stateStore.saveApprovalArtifact(record);
    return record;
  }
}

function renderApprovalDocument({ approval, workflowBundle, traces, title, createdAt }) {
  const relatedTraces = traces.filter((trace) => {
    return (
      trace.approvalRequestId === approval.id ||
      (Array.isArray(trace.approvalRequestIds) && trace.approvalRequestIds.includes(approval.id)) ||
      trace.kind === "approval_override_used" ||
      trace.kind === "approval_retry_executed" ||
      trace.kind === "subagent_governance_hold" ||
      trace.kind === "subagent_spawned"
    );
  });
  const timelineEvents = buildApprovalTimelineEvents(approval, relatedTraces);

  return renderArtifactDocument({
    title: title || approval.title || "approval",
    metadata: [
      `Generated at: ${createdAt}`,
      `Approval id: ${approval.id}`,
      `Kind: ${approval.kind}`,
      `Status: ${approval.status}`,
      `Workflow: ${formatWorkflowLabel(workflowBundle)}`,
      `Summary: ${approval.summary}`
    ],
    sections: [
      {
        title: "Approval Details",
        lines: [
          `- Change summary: ${approval.changeSummary || "(none)"}`,
          `- Policy reason: ${approval.policyReason || "(none)"}`,
          `- Tool: ${approval.toolName || "(none)"}`,
          `- Risk: ${approval.toolRisk || "(none)"}`,
          `- Resolution note: ${approval.resolutionNote || "(none)"}`,
          `- Last retry status: ${approval.lastRetryStatus || "(none)"}`
        ]
      },
      {
        title: "Workflow Context",
        lines: [
          `- Workflow approvals: ${formatApprovalSummaryList(workflowBundle?.approvalRequests || [])}`,
          `- Workflow reviews: ${(workflowBundle?.reviews || []).map((review) => `${review.kind}:${review.status}`).join(", ") || "(none)"}`
        ]
      },
      {
        title: "Related Traces",
        lines: relatedTraces.length > 0
          ? relatedTraces.flatMap((trace) => [
              `### ${trace.id}`,
              `- Kind: ${trace.kind}`,
              `- Created at: ${trace.createdAt}`
            ])
          : ["- No related traces recorded."]
      },
      {
        title: "Timeline",
        lines: renderApprovalTimeline(timelineEvents)
      }
    ],
    notes: [
      "This file was generated by the coding-agent approval artifact exporter.",
      "Export a fresh approval artifact after resolution, override, or retry activity if the evidence changes."
    ]
  });
}

function slugify(value) {
  return value
    .toLowerCase()
    .replace(/[^a-z0-9\u4e00-\u9fa5]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

function buildApprovalTimelineEvents(approval, traces) {
  const events = [
    {
      at: approval.createdAt,
      type: "request",
      eventCode: "approval_requested",
      line: `- ${approval.createdAt}: approval requested (${approval.status})`
    }
  ];

  if (approval.resolvedAt) {
    events.push({
      at: approval.resolvedAt,
      type: "resolution",
      eventCode: approval.status === "approved" ? "approval_approved" : "approval_rejected",
      line: `- ${approval.resolvedAt}: approval ${approval.status}${approval.resolutionNote ? ` (${approval.resolutionNote})` : ""}`
    });
  }

  if (approval.lastRetriedAt) {
    events.push({
      at: approval.lastRetriedAt,
      type: "retry",
      eventCode: "approval_retry_executed",
      line: `- ${approval.lastRetriedAt}: retry executed (${approval.lastRetryStatus || "unknown"})`
    });
  }

  for (const trace of traces) {
    events.push({
      at: trace.createdAt,
      type: mapTraceKindToTimelineGroup(trace.kind),
      eventCode: trace.kind,
      line: `- ${trace.createdAt}: trace ${trace.kind}`
    });
  }

  return events
    .sort((a, b) => String(a.at).localeCompare(String(b.at)));
}

function renderApprovalTimeline(events) {
  if (!events.length) {
    return ["- No timeline events recorded."];
  }

  const grouped = groupTimelineEvents(events);
  return grouped.flatMap((group) => {
    return [
      `### ${group.type}`,
      ...group.events.map((event) => `${event.line} [eventCode=${event.eventCode}]`)
    ];
  });
}

function mapTraceKindToTimelineGroup(kind) {
  if (kind === "approval_requested") {
    return "request";
  }
  if (kind === "approval_override_used") {
    return "override";
  }
  if (kind === "approval_retry_executed") {
    return "retry";
  }
  if (kind === "subagent_governance_hold") {
    return "governance_hold";
  }
  if (kind === "subagent_spawned") {
    return "subagent_spawn";
  }
  return "trace";
}

function groupTimelineEvents(events) {
  const groups = [];
  for (const event of events) {
    const current = groups[groups.length - 1];
    if (current && current.type === event.type) {
      current.events.push(event);
      continue;
    }
    groups.push({
      type: event.type,
      events: [event]
    });
  }
  return groups;
}
